mapper.update:
UPDATE ingest_job
   SET phase = #{phase},
       progress = #{progress},
       message = #{message}
 WHERE id = #{id}
   AND status = 'RUNNING'

UPDATE ingest_job
   SET file_path = #{path},
       file_bytes = #{bytes}
 WHERE id = #{id}

mapper.select:
SELECT id, phase, level, message, created_at
  FROM ingest_job_log
 WHERE job_id = #{jobId}
   AND id > #{afterId}
 ORDER BY id
 LIMIT 300
